mapper.select:
						  DECLARE @ERROR_GB VARCHAR(20) = NULL,
						  @OUT_RESULT_MSG VARCHAR(1000) = NULL


				  BEGIN TRY
				     BEGIN TRAN

						INSERT INTO JAJAERK( J_DATE
			                              , RK1
		                                  , RK2
		                                  , RK3
		                                  , RK4
		                                  , RK5
		                                  , RK6
		                                  , RK7
		                                  , RK8
		                                  , RK9
		                                  , HDDT
                                          , DHDT
                                          , DGDT
                                          , PGDT
                                          , PPDT
                                          , HCDT
                                          , HTDT
                                          , SADT
                                          , INDT
                                          , YADT1
                                          , YADT2
                                          , SCRDT
                                          , PAPDT )
		                             VALUES
		                            	  ( CONVERT(VARCHAR(20), GETDATE(),20)
		                                  , #{RK1}
		                                  , #{RK2}
		                                  , #{RK3}
		                                  , #{RK4}
		                                  , #{RK5}
		                                  , #{RK6}
		                                  , #{RK7}
		                                  , #{RK8}
		                                  , #{RK9}
		                                  , #{HDDT}
                                          , #{DHDT}
                                          , #{DGDT}
                                          , #{PGDT}
                                          , #{PPDT}
                                          , #{HCDT}
                                          , #{HTDT}
                                          , #{SADT}
                                          , #{INDT}
                                          , #{YADT1}
                                          , #{YADT2}
                                          , #{SCRDT}
                                          , #{PAPDT} )





					    SET @ERROR_GB = @@ROWCOUNT;
					    SET @OUT_RESULT_MSG = '저장이 완료되었습니다.';
		    		    COMMIT TRAN;

				    END TRY 

		          BEGIN CATCH 
						ROLLBACK TRAN;
						SET @ERROR_GB = '-1';
						SET @OUT_RESULT_MSG = CONCAT( '오류 메시지 : ', ERROR_MESSAGE()
													, '\r\n줄번호 : ', ERROR_LINE()
			  										, '\r\n오류번호 : ', ERROR_NUMBER()
			  										, '\r\n상태코드 : ', ERROR_STATE()
			  										, '\r\n프로시저명 : ', ERROR_PROCEDURE()
			  										, '\r\n심각도 : ', ERROR_SEVERITY()
			  										, '\r\n오류줄번호 : ', @@ERROR);		     

					END CATCH

			       IF @ERROR_GB = '0'
			          BEGIN
			         	 	SELECT @ERROR_GB AS RESULT
			         			 , '저장된 건이 없습니다.' AS MSG
			         	END 
		           ELSE 
			          BEGIN
						    SELECT @ERROR_GB AS RESULT
						    	 , @OUT_RESULT_MSG AS MSG
					    END
